import{_ as e,o as i,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2019-11-20 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-11-20 :: Ceph Orchestration Meeting","date":"2019-11-20T00:00:00.000Z","updated":"2019-11-26T00:00:00.000Z","tags":["Ceph","Orchestrator","Distributed Storage","Code Review","Test Framework"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-11-20_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-11-20_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-11-20_-_-_Ceph_Orchestration_Meeting.md"};function o(s,t,n,h,u,c){return i(),r("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期</strong>: 2019年11月20日</li><li><strong>参会人员</strong>: Sebastian, Tim, Keifa, Josh 及其他相关人员</li><li><strong>主持人</strong>: Sebastian</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Orchestrator 测试改进</strong></p><ul><li>讨论了SSHFS Writer的实现，这将有助于改进Orchestrator的测试流程。</li><li>指出使用Rook进行测试，并期待Forger的进展。</li></ul></li><li><p><strong>代码审查与集成问题</strong></p><ul><li>Keifa报告了一个待审查的贴纸问题，并请求团队成员进行审查。</li><li>Tim表示他将在接下来的两周内专注于下游工作，并愿意在离开前帮助审查代码。</li></ul></li><li><p><strong>CI 和测试框架</strong></p><ul><li>Josh讨论了关于Rook的CI进展，尽管遇到了时区和可用性的挑战。</li><li>提出对Orchestrator特定测试的需求，但目前进展缓慢。</li></ul></li><li><p><strong>技术问题与解决方案</strong></p><ul><li>讨论了关于IP地址包的问题，该问题影响了SSH Orchestrator的测试。</li><li>提到需要加入GitHub的Orchestrator团队以更好地协作。</li></ul></li><li><p><strong>项目进展与未来计划</strong></p><ul><li>讨论了关于设备ID属性的实现，这将有助于改进设备管理。</li><li>提到Rook正在开发的一个零售功能。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>需要尽快解决IP地址包的问题，以确保测试的顺利进行。</li><li>Tim将在离开前帮助审查代码，团队成员应提前请求他的帮助。</li><li>需要加入GitHub的Orchestrator团队以加强协作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续推进SSHFS Writer的实现，以改进Orchestrator的测试。</li><li>解决IP地址包的问题，并确保相关PR得到及时审查。</li><li>加入GitHub的Orchestrator团队，以更好地管理和协作项目。</li><li>继续关注设备ID属性的实现，并确保其对设备管理的影响。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议中提到了一些技术细节和具体问题的讨论，这些需要在会后进一步跟进和解决。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论了所有议题后结束，团队成员将继续推进各自的任务和项目。</li></ul><p><strong>注意</strong>: 会议中提到的具体技术细节和问题需要进一步的技术文档和代码审查来确保准确性和实施的可行性。</p>',14)])])}const p=e(l,[["render",o]]);export{d as __pageData,p as default};
